import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 200;
// 가정: 결재문서와 교육신청을 잇는 연계 업무 유형 값
const APPROVAL_BUSINESS_TYPE = 'edu_application';
// 가정: 반려 사유가 비어 있어도 처리 완료를 표시하기 위한 기본 문구
const REJECT_FALLBACK = '반려';
const STATUSES = ['신청', '승인', '승인취소'];

function idOf(value: unknown, label: string): string {
  const text = String(value ?? '').trim();
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label} 값이 올바르지 않습니다.`);
  }
  return text;
}

function optionalIdOf(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return idOf(value, label);
}

function intOf(value: unknown, fallback: number, label: string): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const text = String(value).trim();
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label} 값이 올바르지 않습니다.`);
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr01503Controller {
  @Post('/edu-applications')
  @HttpCode(200)
  async createEduApplication(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const sessionId = idOf(data['eduSessionId'], '교육차수');
    const rawReason = data['applicationReason'];
    if (rawReason !== undefined && rawReason !== null && typeof rawReason !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 사유 형식이 올바르지 않습니다.');
    }
    const reason = rawReason ? rawReason : null;
    return transaction(async (db) => {
      const sessions = await db.query(
        'SELECT edu_session_id FROM edu_session WHERE edu_session_id = CAST(:sessionId AS bigint)',
        { sessionId },
      );
      if (sessions.length === 0) {
        throw new ApiError(404, 'EDU_SESSION_NOT_FOUND', '교육차수를 찾을 수 없습니다.');
      }
      const applied = await db.query(
        'SELECT edu_application_id FROM edu_application WHERE edu_session_id = CAST(:sessionId AS bigint) AND employee_id = CAST(:userId AS bigint)',
        { sessionId, userId: user.id },
      );
      const attending = await db.query(
        'SELECT edu_attendee_id FROM edu_attendee WHERE edu_session_id = CAST(:sessionId AS bigint) AND employee_id = CAST(:userId AS bigint)',
        { sessionId, userId: user.id },
      );
      if (applied.length > 0 || attending.length > 0) {
        throw new ApiError(409, 'EDU_APPLICATION_DUPLICATED', '이미 신청했거나 신청할 수 없는 차수입니다.');
      }
      const rows = await db.query(
        `INSERT INTO edu_application (edu_session_id, employee_id, application_reason, status, created_at, updated_at)
         VALUES (CAST(:sessionId AS bigint), CAST(:userId AS bigint), :reason, '신청', now(), now())
         RETURNING edu_application_id AS "eduApplicationId", status`,
        { sessionId, userId: user.id, reason },
      );
      return rows[0];
    });
  }

  @Get('/edu-applications')
  async listEduApplications(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '인사 담당자');
    const query = checks.queryOf(req.query);
    const page = intOf(query['page'], 0, 'page');
    const size = Math.min(intOf(query['size'], DEFAULT_PAGE_SIZE, 'size'), MAX_PAGE_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size 값이 올바르지 않습니다.');
    }
    const sessionId = optionalIdOf(query['eduSessionId'], '교육차수');
    const rawStatus = query['status'];
    const status = rawStatus === undefined || rawStatus === null || rawStatus === '' ? null : String(rawStatus);
    if (status !== null && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 상태 값이 올바르지 않습니다.');
    }
    const where = `WHERE (CAST(:sessionId AS bigint) IS NULL OR edu_session_id = CAST(:sessionId AS bigint))
      AND (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))`;
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT edu_application_id AS "eduApplicationId", edu_session_id AS "eduSessionId",
                employee_id AS "employeeId", status, reject_reason AS "rejectReason"
         FROM edu_application ${where}
         ORDER BY edu_application_id DESC
         LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { sessionId, status, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS total FROM edu_application ${where}`,
        { sessionId, status },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/edu-applications/:eduApplicationId/apply-approval-result')
  @HttpCode(200)
  async applyEduApplicationApprovalResult(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const applicationId = idOf(req.params['eduApplicationId'], '교육신청 ID');
    const data = checks.inputOf(req.body);
    const approved = data['approved'];
    if (typeof approved !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 여부를 입력하세요.');
    }
    const rawReason = data['rejectReason'];
    if (rawReason !== undefined && rawReason !== null && typeof rawReason !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '반려 사유 형식이 올바르지 않습니다.');
    }
    const rejectReason = rawReason ? rawReason : REJECT_FALLBACK;
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT edu_application_id AS "eduApplicationId", edu_session_id AS "eduSessionId",
                employee_id AS "employeeId", approval_document_id AS "approvalDocumentId",
                status, reject_reason AS "rejectReason"
         FROM edu_application
         WHERE edu_application_id = CAST(:applicationId AS bigint)
         FOR UPDATE`,
        { applicationId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EDU_APPLICATION_NOT_FOUND', '교육신청 건을 찾을 수 없습니다.');
      }
      const current = found[0];
      // 가정: 반려는 상태를 '신청'으로 두고 반려 사유를 남기므로, 사유가 있으면 처리된 건으로 본다
      if (current.status !== '신청' || current.rejectReason) {
        throw new ApiError(409, 'EDU_APPLICATION_ALREADY_PROCESSED', '이미 처리된 신청 건입니다.');
      }
      if (!approved) {
        await db.execute(
          `UPDATE edu_application SET reject_reason = :rejectReason, updated_at = now()
           WHERE edu_application_id = CAST(:applicationId AS bigint)`,
          { applicationId, rejectReason },
        );
        return { status: '신청' };
      }
      let documentId = current.approvalDocumentId;
      if (documentId === null || documentId === undefined) {
        const docs = await db.query(
          `SELECT approval_document_id AS "approvalDocumentId" FROM approval_document
           WHERE linked_business_type = :businessType AND linked_business_id = CAST(:applicationId AS bigint)
           ORDER BY approval_document_id DESC LIMIT 1`,
          { businessType: APPROVAL_BUSINESS_TYPE, applicationId },
        );
        if (docs.length === 0) {
          throw new ApiError(502, 'APPROVAL_LINK_FAILED', '연계된 결재문서를 찾을 수 없습니다.');
        }
        documentId = docs[0].approvalDocumentId;
      }
      await db.execute(
        `UPDATE edu_application
         SET status = '승인', approval_document_id = CAST(:documentId AS bigint),
             reject_reason = NULL, approved_at = now(), updated_at = now()
         WHERE edu_application_id = CAST(:applicationId AS bigint)`,
        { applicationId, documentId: String(documentId) },
      );
      await db.execute(
        `INSERT INTO edu_attendee (edu_session_id, employee_id, edu_application_id, created_at, updated_at)
         VALUES (CAST(:sessionId AS bigint), CAST(:employeeId AS bigint), CAST(:applicationId AS bigint), now(), now())
         ON CONFLICT (edu_session_id, employee_id) DO NOTHING`,
        { sessionId: String(current.eduSessionId), employeeId: String(current.employeeId), applicationId },
      );
      return { status: '승인' };
    });
  }
}

