import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  Filters,
  ErrorText,
  Num,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['승인', '승인'],
  ['승인취소', '승인취소'],
];
const RESULT_OPTIONS: [string, string][] = [
  ['true', '승인'],
  ['false', '반려'],
];

function canProcess(row: Row): boolean {
  return row.status === '신청' && !row.rejectReason;
}

export default function FnSfr01503Page({ role, notify }: PageProps) {
  const [sessionDraft, setSessionDraft] = useState<number | string>('');
  const [statusDraft, setStatusDraft] = useState('');
  const [applied, setApplied] = useState({ eduSessionId: '' as number | string, status: '' });
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [target, setTarget] = useState<Row | null>(null);
  const [newSessionId, setNewSessionId] = useState<number | string>('');
  const [newReason, setNewReason] = useState('');
  const [result, setResult] = useState('');
  const [rejectReason, setRejectReason] = useState('');

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/edu-applications', role, undefined, {
        eduSessionId: applied.eduSessionId,
        status: applied.status,
        page,
        size: SIZE,
      }),
    [role, applied, page],
  );
  const waiting = useData<Page>(
    () => call<Page>('GET', '/edu-applications', role, undefined, { status: '신청', page: 0, size: 5 }),
    [role],
  );

  function refresh() {
    list.reload();
    waiting.reload();
  }

  function openProcess(row: Row) {
    setResult('');
    setRejectReason('');
    setTarget(row);
  }

  const columns = [
    { key: 'eduApplicationId', label: '교육신청 ID' },
    { key: 'eduSessionId', label: '교육차수', render: (r: Row) => <RefName table="edu_session" role={role} value={r.eduSessionId} /> },
    { key: 'employeeId', label: '신청자', render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} /> },
    { key: 'status', label: '신청 상태', render: (r: Row) => <Badge value={r.status} /> },
    { key: 'rejectReason', label: '반려 사유' },
    {
      key: 'action',
      label: '처리',
      render: (r: Row) =>
        canProcess(r) ? (
          <button type="button" onClick={(e) => { e.stopPropagation(); openProcess(r); }}>
            결재 결과 반영
          </button>
        ) : null,
    },
  ];

  const waitingColumns = [
    { key: 'eduSessionId', label: '교육차수', render: (r: Row) => <RefName table="edu_session" role={role} value={r.eduSessionId} /> },
    { key: 'employeeId', label: '신청자', render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} /> },
    {
      key: 'action',
      label: '처리',
      render: (r: Row) =>
        canProcess(r) ? (
          <button type="button" onClick={() => openProcess(r)}>처리</button>
        ) : null,
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신청 현황</h2>
        <Tiles
          items={[
            ['전체 신청', <Num value={list.data?.total ?? 0} />],
            ['신청 상태', <Num value={waiting.data?.total ?? 0} />],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>교육신청 내역</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ eduSessionId: sessionDraft, status: statusDraft });
          }}
          onReset={() => {
            setSessionDraft('');
            setStatusDraft('');
            setPage(0);
            setApplied({ eduSessionId: '', status: '' });
          }}
        >
          <Field label="교육차수">
            <LookupSelect table="edu_session" role={role} value={sessionDraft} onChange={setSessionDraft} placeholder="전체" />
          </Field>
          <Field label="신청 상태">
            <Select value={statusDraft} onChange={setStatusDraft} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={() => { setNewSessionId(''); setNewReason(''); setCreating(true); }}>
            교육 신청
          </button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable columns={columns} rows={list.data?.items ?? []} onRowClick={setDetail} empty="교육신청 내역이 없습니다." />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>처리 대기</h2>
        {waiting.error ? <ErrorText text={waiting.error} /> : null}
        <DataTable columns={waitingColumns} rows={waiting.data?.items ?? []} empty="처리 대기 건이 없습니다." />
      </section>

      {creating ? (
        <Drawer title="교육 신청" onClose={() => setCreating(false)}>
          <Form
            submit="신청"
            onSubmit={async () => {
              if (newSessionId === '' || newSessionId === null) {
                throw new Error('교육차수를 선택하세요.');
              }
              await call('POST', '/edu-applications', role, {
                eduSessionId: newSessionId,
                applicationReason: newReason,
              });
              notify('교육을 신청했습니다.');
              setCreating(false);
              refresh();
            }}
          >
            <Field label="교육차수" required>
              <LookupSelect table="edu_session" role={role} value={newSessionId} onChange={setNewSessionId} />
            </Field>
            <Field label="신청 사유" wide>
              <TextInput value={newReason} onChange={setNewReason} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {target ? (
        <Drawer title="전자결재 결과 반영" onClose={() => setTarget(null)}>
          <Form
            submit="반영"
            onSubmit={async () => {
              if (result === '') {
                throw new Error('승인 여부를 선택하세요.');
              }
              await call('POST', `/edu-applications/${target.eduApplicationId}/apply-approval-result`, role, {
                approved: result === 'true',
                rejectReason,
              });
              notify('결재 결과를 반영했습니다.');
              setTarget(null);
              refresh();
            }}
          >
            <Field label="교육차수">
              <RefName table="edu_session" role={role} value={target.eduSessionId} />
            </Field>
            <Field label="신청자">
              <RefName table="employee" role={role} value={target.employeeId} />
            </Field>
            <Field label="승인 여부" required>
              <Select value={result} onChange={setResult} options={RESULT_OPTIONS} />
            </Field>
            <Field label="반려 사유" wide>
              <TextInput value={rejectReason} onChange={setRejectReason} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {detail ? (
        <Drawer title="교육신청 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['교육신청 ID', String(detail.eduApplicationId ?? '')],
              ['교육차수', <RefName table="edu_session" role={role} value={detail.eduSessionId} />],
              ['신청자', <RefName table="employee" role={role} value={detail.employeeId} />],
              ['신청 상태', <Badge value={detail.status} />],
              ['반려 사유', String(detail.rejectReason ?? '')],
            ]}
          />
          {canProcess(detail) ? (
            <button type="button" onClick={() => { const row = detail; setDetail(null); openProcess(row); }}>
              결재 결과 반영
            </button>
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
